import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int channels,
    int height,
    int width,
    int out_channels,
    int kernel_h,
    int kernel_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int out_h,
    int out_w
) {
    int batch_idx = blockIdx.x;
    int out_ch_idx = blockIdx.y;
    int out_h_idx = blockIdx.z * blockDim.x;
    int out_w_idx = threadIdx.x;

    if (batch_idx >= batch_size || out_ch_idx >= out_channels || 
        out_h_idx >= out_h || out_w_idx >= out_w) return;

    // Shared memory for input tile
    extern __shared__ half shared_input[];

    // Initialize accumulator
    float acc = 0.0f;

    // Loop over input channels and kernel elements
    for (int ch = 0; ch < channels; ch++) {
        for (int kh = 0; kh < kernel_h; kh++) {
            for (int kw = 0; kw < kernel_w; kw++) {
                int ih = out_h_idx * stride_h + kh - pad_h;
                int iw = out_w_idx * stride_w + kw - pad_w;

                // Check bounds
                if (ih >= 0 && ih < height && iw >= 0 && iw < width) {
                    int input_idx = batch_idx * (channels * height * width) +
                                   ch * (height * width) +
                                   ih * width + iw;

                    int weight_idx = out_ch_idx * (channels * kernel_h * kernel_w) +
                                    ch * (kernel_h * kernel_w) +
                                    kh * kernel_w + kw;

                    acc += (float)input[input_idx] * (float)weight[weight_idx];
                }
            }
        }
    }

    // Write result
    int output_idx = batch_idx * (out_channels * out_h * out_w) +
                    out_ch_idx * (out_h * out_w) +
                    out_h_idx * out_w + out_w_idx;

    output[output_idx] = __float2half(acc);
}

// Wrapper function for easier calling
extern "C" void launch_conv2d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int channels,
    int height,
    int width,
    int out_channels,
    int kernel_h,
    int kernel_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int out_h,
    int out_w
) {
    dim3 grid(batch_size, out_channels, (out_h + 31) / 32);
    dim3 block(32);
    size_t shared_mem_size = sizeof(half) * channels * kernel_h * kernel_w * 2;

    conv2d_kernel<<<grid, block, shared_mem_size>>>(
        input, weight, output, batch_size, channels, height, width,
        out_channels, kernel_h, kernel_w, stride_h, stride_w, pad_h, pad_w,
        out_h, out_w
    );
}
"""

# Python wrapper
def create_model_new():
    # Compile the CUDA extension
    module = load_inline(
        name="conv2d_cuda",
        cpp_sources=[],
        cuda_sources=[cuda_source],
        functions=["launch_conv2d_kernel"],
        verbose=True
    )

    class ModelNew(torch.nn.Module):
        def __init__(self, num_classes=1000):
            super(ModelNew, self).__init__()
            self.conv1 = torch.nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)
            self._module = module

        def forward(self, x):
            # Convert to fp16 if needed
            if x.dtype != torch.float16:
                x = x.to(torch.float16)

            # Get parameters
            batch_size, channels, height, width = x.shape
            out_channels = self.conv1.out_channels
            kernel_h, kernel_w = self.conv1.kernel_size
            stride_h, stride_w = self.conv1.stride
            pad_h, pad_w = self.conv1.padding
            out_h = (height + 2 * pad_h - kernel_h) // stride_h + 1
            out_w = (width + 2 * pad_w - kernel_w) // stride_w + 1

            # Prepare tensors
            weight = self.conv1.weight.data.contiguous()
            bias = self.conv1.bias.data.contiguous() if self.conv1.bias is not None else None

            # Allocate output tensor
            output = torch.empty(batch_size, out_channels, out_h, out_w, dtype=torch.float16, device=x.device)

            # Launch kernel
            self._module.launch_conv2d_kernel(
                x.data_ptr(),
                weight.data_ptr(),
                output.data_ptr(),
                batch_size,
                channels,
                height,
                width,
                out_channels,
                kernel_h,
                kernel_w,
                stride_h,
                stride_w,
                pad_h,
                pad_w,
                out_h,
                out_w
            )

            # Add bias if present
            if bias is not None:
                bias_expanded = bias.view(1, -1, 1, 1)
                output = output + bias_expanded

            return output

    return ModelNew

ModelNew = create_model_new()
